public Answer answer(
        String question,
        String userId
) {
    Embedding questionEmbedding =
        embeddingService.embed(
            question
        );

    List<DocumentChunk> chunks =
        vectorStore.search(
            questionEmbedding,
            MetadataFilter
                .byUserPermissions(
                    userId
                ),
            5
        );

    if (chunks.isEmpty()) {
        return Answer
            .notEnoughContext();
    }

    String context =
        buildContext(chunks);

    return llm.generate("""
        Answer only from the context.
        If the answer is not in the context,
        say you don't know.

        Context:
        %s

        Question:
        %s
        """.formatted(
            context,
            question
        ));
}
